    async convertPoLineToLineTable(e: any) {
      if (!e || !e.detail) {
        return;
      }

      try {
        if (this.is_view_readonly) {
          return;
        }
        let response: any;
        this.processing = true;

        const po_numbers = this.getPoNumbers(e.detail) as string | Blob;
        let token: string = await this.getToken();
        let formData = new FormData();
        formData.append('data', JSON.stringify(this.record));
        formData.append('purchase_order_numbers', po_numbers);
        formData.append('org_id', getOrgId());
        response = await axios.post(api.get_table_from_po_numbers, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw 'Api response error';
        }
        // name: "PO_CONVERTED_TABLE"
        this.record = response.data.data;
        this.initPage();
        this.debounceAutoSaveFunc();
        this.TableDragModeHandler({ detail: false });
      } catch (err: any) {
        if (
          err != null &&
          typeof err == 'object' &&
          err.hasOwnProperty('message')
        ) {
          notify.error(err.message);
          return;
        }
        notify.error(err);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    getPoNumbers(value: any) {
      if (Array.isArray(value)) {
        return value.join();
      }

      if (
        (typeof value === 'string' || value instanceof String) &&
        value != ''
      ) {
        return value;
      }

      throw 'No Purchase number found';
    },
    async autoPoMatch() {
      try {
        this.processing = true;
        if (this.is_view_readonly) {
          return false;
        }
        const po_items = this.getPurchaseOrderData();
        if (!po_items || Object.keys(po_items).length === 0) {
          throw { message: 'No Po Lines Found' };
        }

        if (
          !this.record.tables ||
          this.record.tables.length == 0 ||
          !this.record.tables[0].hasOwnProperty('rows') ||
          this.record.tables[0].rows.length == 0
        ) {
          throw { message: 'No Line Table found' };
        }

        const data = {
          data: JSON.stringify(this.record),
        };
        const response = await documentPOApiService.autoMatch_v2(data);
        if (response.success === false) {
          throw response;
        }

        this.record = response.data;
        await this.syncDataAfterAutoMatch(false);
        return true;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return false;
      } finally {
        this.processing = false;
      }
    },

    // DOCB-8053: the "Auto Match" button. Until now it only matched — the
    // export step lived solely in the one-shot page-load check
    // (`checkAutoExport`), so with "PO Auto Match and Export" switched on a
    // user had to go back to the dashboard and reopen the document to get it
    // exported. Now a successful click-triggered match applies the same export
    // gates as the page-load path and exports right away.
    async autoPoMatchAndExport() {
      return autoMatchThenExport({
        autoPoMatch: () => this.autoPoMatch(),
        getRecord: () => this.record,
        getPendingAmount: () => this.pending_amount,
        getExportBtns: () => this.$refs['exportBtns'] as any,
      });
