    async searchPurchaseOrderList(val: string, update: any, abort: any) {
      if (!this.record.editable || isEmptyString(val) || val.length < 2) {
        abort();
        return;
      }

      try {
        this.processing = true;
        val = this.removeSpaces(val);
        let po_number_options: any = [];
        let po_numbers = (await this.getPONumberMatchlist(val)) as dynamicObj;
        this.po_search = val;

        if (objLen(po_numbers) > 1) {
          po_numbers.forEach((item: any, index: number) => {
            const po_number = item.purchase_order_number;
            po_number_options.push(
              Object.assign(
                {},
                {
                  value: po_number,
                  label: po_number,
                },
              ),
            );
          });
        }

        if (objLen(po_numbers) == 0) {
          po_number_options.push(
            Object.assign(
              {},
              {
                value: 'no_data_found',
                label: this.$t('no_data_found'),
              },
            ),
          );
        }

        update(() => {
          this.po_number_options = po_number_options;
        });

        if (objLen(po_numbers) == 1) {
          this.getSelectedPOitems(po_numbers[0].purchase_order_number);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    displayPONumbersAsOption(po_number: string) {
      let label =
        '<strong>' + po_number.substr(0, this.po_search.length) + '</strong>';
      label += po_number.substr(this.po_search.length);
      return label;
    },
    async getPONumberMatchlist(purchaseOrder: string) {
      let response: any;
      let purchaseOrderItems = [] as dynamicObj[];
      try {
        let queryParams = '?keyword=' + purchaseOrder;
        let token: string = await this.getToken();

        response = await axios.get(
          addOrgIdQueryString(api.get_purchase_orders_list + queryParams),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (response.data.success !== false) {
          purchaseOrderItems = response.data;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }

      return purchaseOrderItems;
    },
    getPoFieldValue() {
      this.record.fields.forEach((field: any, index: any) => {
        if (field.name === 'purchase_order') {
          this.poFieldValue = field.formatted_value;
        }
      });
    },
    isDeleteAble(poNumber: string) {
      if (!poNumber) {
        return true;
      }
      if (poNumber === this.poFieldValue) {
        return false;
      }
      return true;
    },
    proceedToCloseTab(index: string) {
      if (this.is_view_readonly) {
        return;
      }

      if (!index) {
        this.removeFromPoItems(index);
        this.initPage();
        return;
      }

      if (this.isDeleteAble(index)) {
        this.delete_tab_po_number = index;
        this.delete_tab_confirmation = true;
      }
    },

    cleanupPoMatched() {
      if (!this.record || !this.record.po_multi_matched) {
        return;
      }

      const compact_po_lines = this.getCompactPoLines();
      if (compact_po_lines.length == 0) {
        this.record.po_multi_matched = [];
        this.syncPoMatched();
        return;
      }

      const compact_line_items = this.getCompactLineItems();
      if (compact_line_items.length == 0) {
        this.record.po_multi_matched = [];
        this.syncPoMatched();
        return;
      }

      const remove_indexes = [] as number[];
      for (let [index, record] of this.record.po_multi_matched.entries()) {
        let table_line_ids: string[] = this.getLineIds(record);
        let purchase_order_numbers: string[] =
          this.getPurchaseOrderNumbers(record);

        for (let table_line_id of table_line_ids) {
          if (compact_line_items.includes(table_line_id) == false) {
            if (!remove_indexes.includes(index)) {
              remove_indexes.push(index);
            }
          }
        }

        for (let po_line_id of purchase_order_numbers) {
          if (compact_po_lines.includes(po_line_id) == false) {
            if (!remove_indexes.includes(index)) {
              remove_indexes.push(index);
            }
          }
        }
      }

      if (remove_indexes.length == 0) {
        return;
      }

      this.record.po_multi_matched = this.record.po_multi_matched.filter(
        (value: any, index: number) => {
          return !remove_indexes.includes(index);
        },
      );

      this.syncPoMatched();
    },

    syncPoMatched(saveData = true) {
      this.initLineItems();
      this.initPoLines();
      if (saveData) {
        this.debounceAutoSaveFunc();
      }
    },

    initPoLines() {
      const event = new CustomEvent('init_po_lines', {});
      document.dispatchEvent(event);
    },

    getCompactLineItems() {
      const line_items = [] as string[];

      const rows = (
        $('#line_item_table') as HTMLElement
      ).querySelectorAll<HTMLElement>('.line-item-tr');
      if (rows.length == 0) {
        return line_items;
      }

      for (var i = 0; i < rows.length; i++) {
        let row = rows[i];
        if (row.dataset.id) {
          line_items.push(row.dataset.id);
        }
      }

      return line_items;
    },

    getCompactPoLines() {
      const po_lines = [] as string[];

      if (objLen(this.po_items) == 0) {
        return po_lines;
      }

      for (const [index, lines] of Object.entries(this.po_items)) {
        for (const [line_index, line] of Object.entries(lines)) {
          const item = line as dynamicObj;
          po_lines.push(item.id);
        }
      }
      return po_lines;
    },
    confirmRefreshData(poNumber: string) {
      if (
        this.record.po_multi_matched &&
        this.record.po_multi_matched.length > 0
      ) {
        this.showConfirmSyncDlg = true;
        this.poToRefresh = poNumber;
        return;
      }
      this.refreshAlreadyAddedItem(poNumber);
    },
    async refreshAlreadyAddedItem(poSearch: string) {
      try {
        if (this.is_view_readonly) {
          return;
        }
        this.processing = true;

        if (this.poItemsWithUpdates.hasOwnProperty(poSearch)) {
          this.po_preview_items = this.poItemsWithUpdates[poSearch];
        } else {
          this.po_preview_items = (await this.getPOitems(
            poSearch,
          )) as dynamicObj;
        }

        this.po_preview = true;
        this.po_search = poSearch;
        this.addToPoItemsList();
        this.processing = false;

        this.record.po_multi_matched = [];

        // refresh all the tables
        const event = new CustomEvent('reload_received_delivery_lines', {});
        document.dispatchEvent(event);
        this.syncPoMatched();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }

      this.poToRefresh = '';
      delete this.poItemsWithUpdates[poSearch];
    },

    displayAdvanceFilterResults(filteredPo: any) {
      this.showAdanceFilter = false;
      this.po_search = '';
      this.po_preview_items = [] as any;
      this.po_search_keyword = '';
      if (!filteredPo.data || filteredPo.data.length == 0) {
        notify.error(this.$t('no_data_found'));
      }
      this.totalRecords = filteredPo.metadata.total_results;
      this.po_preview_items = filteredPo.data;
    },
    async proceedPoSelection(poNumber: string) {
      try {
        if (isEmptyString(poNumber) || isUndefinedOrNull(poNumber)) {
          return;
        }

        this.processing = true;
        this.po_search = poNumber;
        this.po_preview_items = [] as any;
        let po_item = (await this.getPOitems(this.po_search)) as dynamicObj;
        this.po_preview_items = po_item;

        if (
          isEmptyString(this.po_search) ||
          isUndefinedOrNull(this.po_search)
        ) {
          this.clearSearch();
          return;
        }

        this.addToPoItemsList();
      } catch (err) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    triggerAutoMatch() {
      this.execute_auto_export = true;
      this.checkAutoExport(false);
    },

    async checkAutoExport(auto_export = true) {
      if (!this.execute_auto_export || this.is_view_readonly) {
        return;
      }

      this.execute_auto_export = false;
      this.auto_match_alert = false;
      if (isUndefinedOrNull(this.record.po_multi_matched) || this.record.po_multi_matched.length == 0 ) {
        await this.autoPoMatch();
      } else {
        console.info('Auto Exporting POs');
        this.auto_match_alert = true;
      }

      // DOCB-8053: same gates as the "Auto Match" button (status, pending
      // amount, org switch / document opt-out) live in one helper.
      if (auto_export && shouldAutoExportAfterPoMatch(this.record, this.pending_amount)) {
        // DRFS-741: true marks this as the automatic Auto-Match-and-Export
        // action, so the API can enforce the module switch itself.
        (this.$refs['exportBtns'] as any).confirmAndExport(true);
      }
    },

    async getToleranceLevel() {
      let response: any;
      try {
        this.processing = true;
        // send doc type as query param
        const data = {
          doc_type: this.selected_doc_type,
        };
        response = await documentPOApiService.getToleranceList(data);
        if (!response.success || !response.data) {
          throw response;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }

      this.unit_price_tolerance = response.data.unit_price_tolerance ? response.data.unit_price_tolerance : 0.5;
      this.quantity_tolerance = response.data.quantity_tolerance ? response.data.quantity_tolerance : 0.5;
      this.quantity_tolerance_type = response.data.quantity_tolerance_type ? response.data.quantity_tolerance_type : this.percent;
      this.unit_price_tolerance_type = response.data.unit_price_tolerance_type ? response.data.unit_price_tolerance_type : this.percent;

      this.itemSpecificTolerancesMap.clear();
      if (response.data.hasOwnProperty('item_specific_tolerances')) {
        Object.keys(response.data.item_specific_tolerances).forEach((value: any, index: any) => {
          this.setToleranceForItem(value, response.data.item_specific_tolerances[value]);
        });
      }

      if (response.data.hasOwnProperty('supplier_item_specific_tolerances')) {
        Object.keys(response.data.supplier_item_specific_tolerances).forEach((value: any, index: any) => {
          this.setToleranceForItem(value, response.data.supplier_item_specific_tolerances[value]);
        });
      }
    },
    async updatePoTabs() {
      this.visible_columns = await this.getSavedColumns(
        this.po_table_columns + '_' + this.record.doc_type,
      );
      this.tabsKey++;
    },

    gotoTaskPendingList() {
      useTaskStore().prepareForDocPendingTasks(this.docId);
      this.$router.push('/tasks');
    },

    lineItemsLoaded() {
      if (!this.first_time_view_render) {
        return;
      }
      this.first_time_view_render = false;

      this.verifyMatchedPoIds();
    },

    verifyMatchedPoIds() {
      for (const [table_line_id, line_data] of Object.entries(
        this.po_connected_items,
      )) {
        if (!this.lineDataObj.hasOwnProperty(table_line_id)) {
          this.triggerAutoMatch();
          break;
        }
      }
    },

    setActiveTab() {
      if (objLen(this.po_items) == 0) {
        return;
      }

      if (
        this.tab == '' ||
        !this.po_items.hasOwnProperty(this.tab) ||
        objLen(this.po_items) == 1
      ) {
        this.tab = Object.keys(this.po_items)[0];
      }
    },

    async setupSupplierItemNumbers(po_items: dynamicObj[]) {
      try {
        if (this.is_view_readonly) {
          return;
        }
        let supplier = this.getSupplierId();
        // supplier = '2073';
        if (isEmptyString(supplier)) {
          return;
        }

        let item_numbers = [] as string[];

        if (po_items && objLen(po_items) > 0) {
          for (const [key, items] of Object.entries(this.po_items)) {
            const po_item = items as any;

            if (
              po_item.hasOwnProperty('supplier_item_id') &&
              !this.po_supplier_item_numbers.hasOwnProperty(
                po_item.supplier_item_id,
              )
            ) {
              item_numbers.push(po_item.supplier_item_id);
            }
          }
        }

        const item_numbers_str = item_numbers.join(',');
        await this.getItemNumberDictionary(supplier, item_numbers_str);
      } catch (err) {
        logError(err);
      }
    },

    getSupplierId() {
      let supplier = '';
      if (
        this.record.fields &&
        Array.isArray(this.record.fields) &&
        this.record.fields.length > 0
      ) {
        this.record.fields.forEach((field: any, index: any) => {
          if (field.name !== 'supplier_id') {
            return;
          }

          supplier = field.formatted_value;
        });
      }
      return supplier;
    },

    async getItemNumberDictionary(supplier: string, item_numbers_str: string) {
      try {
        if (
          isEmptyString(supplier) ||
          this.fetched_suppliers.hasOwnProperty(supplier)
        ) {
          return;
        }

        const response = await documentPOApiService.getSupplierItemNumbers({
          supplier_id: supplier,
          item_numbers: item_numbers_str,
        });

        if (!response.hasOwnProperty('success') || response.success === false) {
          throw response;
        }
        this.fetched_suppliers[supplier] = true;
        const data = response.data as dynamicObj;
        for (const [item_number, items] of Object.entries(data)) {
          // make items object for easy access
          const po_items = {} as Record<string, string>;
          for (const [index, item_number] of Object.entries<string>(items)) {
            // Specify item_number as string
            po_items[item_number] = item_number;
          }

          this.po_supplier_item_numbers[item_number] = po_items;
        }
      } catch (err) {
        logError(err);
      }
    },

    routeToBack() {
      try {
        if (history.state.back) {
          this.$router.back();
          return;
        }
        this.$router.push('/field_validation_v1/' + this.docId);
      } catch (err) {
        logError(err);
        this.$router.push('/field_validation_v1/' + this.docId);
      }
    },

    goToAccounting() {
      this.$router.push('/accounting/' + this.$route.params.id);
    },
    async copyToClipboard(text: string | number) {
      try {
        if (!text) {
          return;
        }
        if (typeof text === 'number') {
          text = text.toString();
        }
        await quasarCopyToClipboard(text);
        notify.success(this.$t('success_copy_to_clipboard'));
      } catch (err) {
        notify.error(this.$t('error_copy_to_clipboard'));
      }
    },

    async handleCharges(po_items: dynamicObj) {
      // load charges
      // charges by po number and then item number
      //  take po_items key and check if it has value in charges
      const missing_charges_po = [] as string[];
      for (const [key, value] of Object.entries(po_items)) {
        if (this.charges.hasOwnProperty(key)) {
          continue;
        }
        this.charges[key] = {};
        missing_charges_po.push(key);
      }

      if (missing_charges_po.length == 0) {
        return;
      }

      try {
        const po_numbers = missing_charges_po.join(',');
        const response = await purchaseOrderService.getPoCharges({
          purchase_order_numbers: po_numbers,
        });
        if (response.success === false) {
          throw response;
        }

        for (const [key, value] of Object.entries(response.data)) {
          const charge_line = value as dynamicObj;
          if (!this.charges.hasOwnProperty(charge_line.purchase_order_number)) {
            this.charges[charge_line.purchase_order_number] = {};
          }

          if (
            !this.charges[charge_line.purchase_order_number].hasOwnProperty(
              charge_line.line_number,
            )
          ) {
            this.charges[charge_line.purchase_order_number][
              charge_line.line_number
            ] = [];
          }

          this.charges[charge_line.purchase_order_number][
            charge_line.line_number
          ].push(charge_line);
        }
      } catch (err) {
        logError(err);
      }
    },
    proceedToRouteLeave() {
      this.isSavePending = false;
      this.$router.push(this.routeUrl);
    },
    setSavePendingStatus(status: boolean) {
      this.isSavePending = status;
    },
    setTriggerDocumentLock(isLocked: boolean) {
      this.trigger_document_lock = isLocked;
    },
  },

  beforeRouteLeave: async function (to: any, from: any, next: any) {
    if (this.isSavePending) {
      this.routeUrl = to.fullPath;
      this.showRouteLeaveConfirmation = true;
      return;
    }

    if (typeof this.warning_alert === 'function') {
      this.warning_alert();
    }
    await this.removeCache();
    this.record = {};
    this.fetch_po_items = true;
    next();
  },
  setup() {
    const doc_store = useDocumentStore();
    const {
      record,
      processing,
      doctype,
      auto_saving,
      auto_saved_done,
      error,
      selected_doc_type,
      fetch_po_items,
      bannerBg,
      hasApiData,
    } = storeToRefs(doc_store);
    const {
      getDocumentById,
      getExtAppPODocumentByID,
      saveExtAppDocument,
      saveDocument,
      removeCache,
      setDataToCache,
      removePoConnection,
      getPurchaseOrderNumbers,
      removeAccountingData,
    } = doc_store;

    const auth_token_store = useAuthTokenStore();
    const { token } = storeToRefs(auth_token_store);
    const { setAuthToken } = auth_token_store;

    const po_match_store = usePoMatchStore();
    const {
      table_columns,
      unit_price_tolerance,
      quantity_tolerance,
      itemSpecificTolerancesMap,
      quantity_tolerance_type,
      unit_price_tolerance_type,
      filterModel,
      po_connected_items,
      lineDataObj,
      is_view_readonly,
      po_supplier_item_numbers,
      pending_amount,
      po_preview_columns,
      po_quantity_column,
      isChargesModuleEnabled,
      charges,
      po_preview,
    } = storeToRefs(po_match_store);
    const {
      calculateMatchedTotal,
      buildPoLinesObj,
      setTotallineItem,
      initFilterModel,
      initToleranceModel,
      getSavedColumns,
      setToleranceForItem,
      prepareFilterRequestParams,
      resetPoMatchStore,
      setPoQuantityColumn,
      getPOColumns,
    } = po_match_store;

    const settings_store = useSettingStore();
    const { user_settings, execute_auto_export } = storeToRefs(settings_store);
    const { updateSetting, startSettingsFetch } = settings_store;

    const websocket_store = useWebSocketStore();
    const { connect } = websocket_store;

    const doc_attribute_store = useDocAttributesStore();
    const { fetchAttributes } = doc_attribute_store;
    const { model: docAttributesModel } = storeToRefs(doc_attribute_store);

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const { current_sidebar, sidebarWidthClass, rightSectionClass, toggleSideBar } = useSidebarPanel();
    const { tokenQueryParam } = useImageAuth();

    let data: any = [];
    return {
      current_sidebar,
      sidebarWidthClass,
      rightSectionClass,
      toggleSideBar,
      tokenQueryParam,
      charges,
      bannerBg,
      hasApiData,
      fetch_po_items,
      docAttributesModel,
      execute_auto_export,
      isChargesModuleEnabled,
      getPOColumns,
      releaseDocLock,
      startSettingsFetch,
      quasarCopyToClipboard,
      doctype,
      pending_amount,
      po_supplier_item_numbers,
      fetchAttributes,
      setPoQuantityColumn,
      trigger_document_lock: ref(false),
      resetPoMatchStore,
      is_view_readonly,
      lineDataObj,
      po_connected_items,
      prepareFilterRequestParams,
      filterModel,
      selected_doc_type,
      buildPoLinesObj,
      connect,
      updateSetting,
      initFilterModel,
      getSavedColumns,
      setTotallineItem,
      initToleranceModel,
      setToleranceForItem,
      calculateMatchedTotal,
      doc_fetch_error: ref(error),
      auto_saving,
      auto_saved_done,
      user_settings,
      removeCache,
      saveDocument,
      setAuthToken,
      setDataToCache,
      getDocumentById,
      saveExtAppDocument,
      removePoConnection,
      removeAccountingData,
      getPurchaseOrderNumbers,
      getExtAppPODocumentByID,
      token,
      processing,
      table_columns,
      record,
      tab: ref(''),
      profile: ref(''),
      po_preview,
      confirmDecision: ref(false),
      po_preview_items: ref(data),
      allowPODragButton: ref(true),
      allowPOTableDrag: ref(false),
      po_items: ref({} as dynamicObj),
      fetched_po_items: ref({} as dynamicObj),
      fetched_suppliers: ref({} as dynamicObj),
      poItemsWithUpdates: ref({} as dynamicObj),
      showKeyboardShortcuts: ref(false),
      first_time_view_render: ref(true),
      togglerIcon: ref('chevron_right'),
      baseUrl: DOC2API_URL,
      get_fields: { purchase_order: '', invoice_id: '' } as dynamicObj,
      po_preview_columns,
      po_quantity_column,
      table_name: ref(''),
      auto_save_data: ref(true),
      blockSaveWhileRecalculating: ref(false),
      delete_tab_confirmation: ref(false),
      delete_table_confirmation: ref(false),
      delete_tab_po_number: ref(''),
      ext_table_train: ref(false),
      po_number_options: ref(data),
      po_search: ref(''),
      po_search_keyword: ref(''),
      itemSpecificTolerancesMap,
      unit_price_tolerance,
      quantity_tolerance,
      quantity_tolerance_type,
      unit_price_tolerance_type,
      error,
      auto_match_alert: ref(false),
    };
  },
});
</script>

